function CalendarDBP(p) {
    var NULL = null;
    var _po = NULL;
    var _bindings = NULL;
    var _container = NULL;
    var _calendarTBody = NULL;
    var _dbp = NULL;
    var _state = 'init'; // Can be init | bindComplete
    var _result = NULL;
    var _showTime = false;
    var _showDays = false;
    var _calendarConfig = NULL;
    var _todayLink = NULL;
    var _applyLink = NULL;
    var _closeLink = NULL;
  	var _monthDropdown = NULL;
  	var _yearDropdown = NULL;
    var arrayOfSpinners = ['monthSpinner','yearSpinner','hourSpinner','minSpinner','ampmSpinner'];

    var assertState = function(state) {
        if (_state !== state) {
            throw "Invalid Calendar DBP state [" + _state + "], must be [" + state + "].";
        }
    };

    var setSelectedDropDownValue = function(selValue, domElement) {
        var listLength = domElement.length;
        for (var i = 0; i < listLength; i++) {
            if (domElement.options[i].value == selValue) {
                domElement.options[i].selected = true;
            }
        }
    };

    var populateInputBox = function(args) {
        /*
         * If associated element replaced from the Dom then get it from id or name of the field.
         * Textentry allowed case it will be input element which has name attribute
         * Textentry not allowed case it will be span element which has id attribute
         */
        if (!pega.util.Dom.inDocument(_bindings.associatedElement)) {
            if (_bindings.associatedElement.id) {
                _bindings.associatedElement = document.getElementById(_bindings.associatedElement.id);
            } else if (_bindings.associatedElement.name) {
                _bindings.associatedElement = document.getElementsByName(_bindings.associatedElement.name)[0];
            }
        }
        populateSubmitableField(args);
        var inputsArray = _bindings.associatedElement.getElementsByTagName("input");
        var firstInput = inputsArray[0];
        if (firstInput.type.toLowerCase() != "text") { /*text entry not allowed*/
          
          // BUG-683841 fix: clear the placeholder class for text-entry not allowed
          var imgInput = _bindings.associatedElement.getElementsByTagName("img")[0]; /*extracting image input*/
          var textElem = pega.util.Dom.getPreviousSibling(imgInput); /*get span next to image and update*/
          pega.control.PlaceHolder.removeClass(textElem); /* This will remove placeholder class if exists */
                
            /*replacing the span with date value here if display value using readonly formatting is unchecked, other in success of postvalue*/
            if (firstInput.getAttribute("data-formatting") == null || firstInput.getAttribute("data-formatting") == "") {
                if(firstInput.getAttribute("data-custom-timezone")){
                  textElem.innerHTML = inputsArray[0].getAttribute("data-value");
                }else{
                  textElem.innerHTML = inputsArray[0].value; /*get span next to image and update*/
                }
            } else {
                var e = {
                    "target": firstInput
                }; /*creating a dummy event object to call getReadOnlyFormatting*/
                pega.c.formatter.getReadOnlyFormatting(e, "true");
            }
        }
    };

    /*Populates the Input Box with the selected date incase of Calendar Mode and the hidden input field in case of dropdown mode*/
    var populateSubmitableField = function(args) {
      	//var dateValue = args[1] + "/" + args[0] + "/" + args[2];
        var inputElem = _bindings.associatedElement.getElementsByTagName("input")[0];
        var imgArray = _bindings.associatedElement.getElementsByTagName("img");
        var datePickerImgElem = imgArray && imgArray.length> 0 ? imgArray[0] : false;
        var currentLocale = pega.u.d.CalendarUtil && pega.u.d.CalendarUtil.Locale;
        if (inputElem.getAttribute("data-formatting") === "done" && inputElem.value) {
            inputElem.setAttribute("data-display-value", inputElem.value);
        }
        
        if(inputElem.value && datePickerImgElem){
         var localizedDateTimevalue = pega.u.d.CalendarUtil.localizeDate(args[2], args[1], args[0], args[3], args[4], args[5]);
         var localizedSelDateValue = currentLocale && currentLocale.SELECTED_DATE_LABEL ? currentLocale.SELECTED_DATE_LABEL : "Selected date is";
         var localizedDatepickerValue = currentLocale && currentLocale.DATE_PICKER_LABEL ? currentLocale.DATE_PICKER_LABEL : "Date picker";
         datePickerImgElem.setAttribute('aria-label', localizedSelDateValue +' '+ localizedDateTimevalue + ', '+ localizedDatepickerValue);
        }
        if (_showDays) {
            if (_showTime) {
              var localizedDateTime = pega.u.d.CalendarUtil.localizeDate(args[2], args[1], args[0], args[3], args[4], args[5]);
                if (!inputElem.getAttribute("data-format-method") && !inputElem.parentNode.getAttribute("data-rel-path"))
                    inputElem.setAttribute("data-value", localizedDateTime);
                var customTimeZone = inputElem.getAttribute("data-custom-timezone");
                if(customTimeZone && inputElem.type=="hidden"){
                  var dateTimeInCustomTimezone = pega.u.d.CalendarUtil.convertDateTimeBtwnTimezones(localizedDateTime, customTimeZone, pega.u.d.TimeZone);
                  inputElem.setAttribute("data-value", localizedDateTime);
                  pega.control.PlaceHolder.setValue(inputElem, dateTimeInCustomTimezone); 
                }else{
                  if(inputElem.hasAttribute("data-value") && inputElem.getAttribute("data-value") !== null && inputElem.getAttribute("data-value") !== ""){
                    inputElem.setAttribute("data-value", localizedDateTime);
                  }
                  pega.control.PlaceHolder.setValue(inputElem, localizedDateTime);                  
                }
            } else {
                if (!inputElem.getAttribute("data-format-method") && !inputElem.parentNode.getAttribute("data-rel-path"))
                    inputElem.setAttribute("data-value", pega.u.d.CalendarUtil.localizeDate(args[2], args[1], args[0]));
                pega.control.PlaceHolder.setValue(inputElem, pega.u.d.CalendarUtil.localizeDate(args[2], args[1], args[0]));
            }
        } else { //if Time Picker
            if (!inputElem.getAttribute("data-format-method") && !inputElem.parentNode.getAttribute("data-rel-path"))
                inputElem.setAttribute("data-value", pega.u.d.CalendarUtil.localizeDate(null, null, null, args[0], args[1], args[2]));
            pega.control.PlaceHolder.setValue(inputElem, pega.u.d.CalendarUtil.localizeDate(null, null, null, args[0], args[1], args[2]));
        }

        if (inputElem.getAttribute("data-formatting") && inputElem.getAttribute("data-format-method"))
            inputElem.setAttribute("data-formatting", "yes");
        /* BUG-386541: Hfix-45797 Attach the validation function using validation_validateFromUIEvent */
      if (pega.cl && !pega.cl.isTouchAble()){ 
        if(typeof validation_validateFromUIEvent === "function")
          validation_validateFromUIEvent(pega.util.Event.getEvent(), inputElem); 
      }
    };

    var populateDropDowns = function(args) {
        var selectPrefix = _bindings.associatedElement.id;
        var selects = _bindings.associatedElement.getElementsByTagName("select");
        for (var i = 0; i < selects.length; i++) {
            if (_showDays) {
                if (selects[i].id == selectPrefix + "DySel") {
                    setSelectedDropDownValue(args[0], selects[i]);
                } else if (selects[i].id == selectPrefix + "MoSel") {
                    setSelectedDropDownValue(args[1], selects[i]);
                } else if (selects[i].id == selectPrefix + "YrSel") {
                    setSelectedDropDownValue(args[2], selects[i]);
                } else if (selects[i].id == selectPrefix + "HrSel") {
                    setSelectedDropDownValue(args[3], selects[i]);
                } else if (selects[i].id == selectPrefix + "MiSel") {
                    setSelectedDropDownValue(args[4], selects[i]);
                } else if (selects[i].id == selectPrefix + "ApSel") {
                    setSelectedDropDownValue(args[5], selects[i]);
                }
            } else if (_showTime) {
                if (selects[i].id == selectPrefix + "HrSel") {
                    setSelectedDropDownValue(args[0], selects[i]);
                } else if (selects[i].id == selectPrefix + "MiSel") {
                    setSelectedDropDownValue(args[1], selects[i]);
                } else if (selects[i].id == selectPrefix + "ApSel") {
                    setSelectedDropDownValue(args[2], selects[i]);
                }
            }
        }
        populateSubmitableField(args);
    };

    var onDayCellClick = function(e) {
        var day = p.util.Event.getTarget(e, true).getAttribute("data-day");
        if (day == null) {
            pega.util.Event.stopEvent(e);
            return;
        }
        var args = new Array();
        args.push(day);
        var tbody = document.getElementById("controlCalBody");
        args.push(parseInt(tbody.getAttribute("month")));
        /* Thai Calendar Support. Add 543 to year - HFIX-4964 */
        /*HFIX-40328 : commenting as year in selected date was already incremented by 543 */
        /*if (typeof pega.u.d.Locale != 'undefined' && pega.u.d.Locale == 'th_TH') {
            args.push(parseInt(tbody.getAttribute("year")) + 543);
        } else {
            args.push(parseInt(tbody.getAttribute("year")));
        }*/
        args.push(parseInt(tbody.getAttribute("year")));
        if (_showTime) {
            getSelectedValues(args);
        }

        if (_calendarConfig.d[0] == 0) {
            var inputsArray = _bindings.associatedElement.getElementsByTagName("input");
            var firstInput = inputsArray[0];
            if ((firstInput == null || typeof(firstInput) == "undefined") && pega.util.Event.isIE) {
                var associatedElemId = _bindings.associatedElement.getAttribute("id");
                inputsArray = document.getElementById(associatedElemId).getElementsByTagName("input");
                firstInput = inputsArray[0];
            }
            var imgArray = _bindings.associatedElement.getElementsByTagName("img");
            var imgInput = imgArray && imgArray.length>0 ? imgArray[0] : false;
            var spanEle = "";
            if (firstInput.type.toLowerCase() !== "text" && imgInput) {
                spanEle = pega.util.Dom.getPreviousSibling(imgInput);
            }
            var previousValue = firstInput.getAttribute("data-value") ? firstInput.getAttribute("data-value") : firstInput.value;
            firstInput.prevValue = previousValue;/*HFix-49576 : storing previous value to trigger change event only on change*/
            populateInputBox(args);

            /* Bug-40256: Added code for focussing the pxDateTime field after selecting the date*/


            if (firstInput.type.toLowerCase() !== "text") {
                //var imgInput = _bindings.associatedElement.getElementsByTagName("img")[0];
                //pega.util.Dom.getPreviousSibling(imgInput).focus();
                spanEle.focus();
                if (p && p.cl && p.cl.isTouchAble()) {
                    spanEle.blur(); /*To avoid keyboard in case of mobile, also for readonly fomratting in editable mode*/
                }
            } else {
                firstInput.focus(); /*HFIX-85957 Focusing to input by default after selecting date as the blur event is not targetting for the input*/
                if(imgInput){
                  imgInput.focus();
                } 
                if (p && p.cl && p.cl.isTouchAble()) {
                    firstInput.blur(); /*To avoid keyboard in case of mobile, also for readonly fomratting in editable mode*/
                }
            }


        } else {
          	populateDropDowns(args);
            if (!p.cl.isTouchAble()) {
                //Retaining focus on calendar icon upon its closure
                var calendarNode = _bindings.associatedElement.getElementsByTagName("span");
                calendarNode[0].focus();
                //var selects = _bindings.associatedElement.getElementsByTagName("select");
                //selects[selects.length - 1].focus();
            } /*For Dropdowns with Calendar, given focus to the right-most dropdown when dismissing the Calendar.*/
        }
        /*
        var srcElement = _bindings.associatedElement.getElementsByTagName("input")[0]; //input element containing date value
        pega.u.d.CalendarUtil.fireClientEvents(srcElement);
        */
        _po.close('cancelfireevents');
        return false;
    };
  
  	var getSelectedValues = function(args){
      	args = args || [];
      	if(_calendarConfig.calendarNavigation){
          	args = pega.u.d.getCalendar().getTimeValues(args);
        }
      	else{
          	args.push(document.getElementById("hourDrop").value);
           	args.push(document.getElementById("minuteDrop").value);
            args.push(document.getElementById("amPmDrop").value);
        }
      	return args;
    };
    
    var onTodayClick = function() {
      pega.u.d.getCalendar().setToday(); 
    }
    var onCloseClick = function() {
        pega.u.d.getCalendar().closeCalendar();
    }
    var onApplyClick = function() {
        pega.u.d.getCalendar().applyDate();
    }
    var onMonthSelect = function(e) {
        pega.u.d.getCalendar().onMonthSelect(e);
    }
    var onYearSelect = function(e) {
        pega.u.d.getCalendar().onYearSelect(e);
    }
    
    var dateInputChangeHandler = function (e){
      if(e.keyCode !== 13) return;
      var ariaLiveSpan = document.getElementById("datePickerspinner");
      var spinnerElem = e.target.parentElement.parentElement.childNodes;
      var hasInputField = spinnerElem && spinnerElem[1].nodeName === "INPUT";
      var associatedInputFieldval = hasInputField && spinnerElem[1].value;
      ariaLiveSpan.innerHTML = associatedInputFieldval?associatedInputFieldval:'';
    }
    
    var attachListenerForspinner = function(){
      for(var i =0;i<arrayOfSpinners.length;i++){
        const upelm = document.getElementById(arrayOfSpinners[i]+"-input-up");
        const downelm = document.getElementById(arrayOfSpinners[i]+"-input-down");
        p.util.Event.addListener(upelm, 'keyup', dateInputChangeHandler, _dbp);
        p.util.Event.addListener(downelm, 'keyup', dateInputChangeHandler, _dbp);
      }
    }
    
    var detachListenerForspinner = function(){
      for(var i =0;i<arrayOfSpinners.length;i++){
        const upelm = document.getElementById(arrayOfSpinners[i]+"-input-up");
        const downelm = document.getElementById(arrayOfSpinners[i]+"-input-down");
        p.util.Event.removeListener(upelm, 'keyup', dateInputChangeHandler);
        p.util.Event.removeListener(downelm, 'keyup', dateInputChangeHandler);
      }
    }

    var attachEvents = function() {
        _container = _po.getContentContainerElement();
        _calendarTBody = document.getElementById("controlCalBody");
        _todayLink = document.getElementById("todayLink");
        _closeLink = document.getElementById("closeLink");
        _applyLink = document.getElementById("applyLink");
      
        var eventType = "click";

        // Tap event is deprecated as part of this US-130296
        /* if(p.cl.isTouchAble()){
        	eventType = "tap";
        } */
        p.util.Event.addListener(_calendarTBody, eventType, onDayCellClick, _dbp);
        if (_todayLink) p.util.Event.addListener(_todayLink, eventType, onTodayClick, _dbp);
        p.util.Event.addListener(_closeLink, eventType, onCloseClick, _dbp);
        if (_applyLink) p.util.Event.addListener(_applyLink, eventType, onApplyClick, _dbp);
      	
      	if(!_calendarConfig.calendarNavigation){
          	_monthDropdown = document.getElementById("monDrop");
      		_yearDropdown = document.getElementById("yearDrop");
      		p.util.Event.addListener(_monthDropdown, 'change', onMonthSelect, _dbp);
        	p.util.Event.addListener(_yearDropdown, 'change', onYearSelect, _dbp);
        }  
          
    };

    /* BUG-147136: today hyperlink not working. exposing onDayCellClick function to call on click of the today link */
    this._triggerDayClick = function(dateLink) {
        onDayCellClick({
            target: dateLink
        });
    };

    this.setParams = function(args) {
        _showTime = args[0];
        _showDays = args[1];
    };

    this.bind = function(po, bindings) {
        assertState('init');
        _dbp = this;
        this.po = _po = po;
        _bindings = bindings;
        if (_bindings.associatedElement.tagName == "INPUT") {
            _bindings.associatedElement = _bindings.associatedElement.parentNode;
        }
        _calendarConfig = p.c.eventParser.parseJSON(_bindings.associatedElement.getAttribute('data-calendar'));
      	//_calendarConfig.calendarNavigation = 1;
        
        if (_showDays || _showTime) {
          attachEvents();
          attachListenerForspinner();
        }
        
        _state = 'bindComplete';
    };

    var detachEvents = function() {
        var eventType = "click";
        // Tap event is deprecated as part of this US-130296
        /*
		if(p.cl.isTouchAble()){
			eventType = "tap";
		}*/

        p.util.Event.removeListener(_calendarTBody, eventType, onDayCellClick);
        if (_todayLink) 
          p.util.Event.removeListener(_todayLink, eventType, onTodayClick);
        p.util.Event.removeListener(_closeLink, eventType, onCloseClick);
        if (_applyLink)
          p.util.Event.removeListener(_applyLink, eventType, onApplyClick);
      	
      	if(_calendarConfig.calendarNavigation){
          	pega.u.d.getCalendar().destroySpinners();
        }
      	else{
      		p.util.Event.removeListener(_monthDropdown, 'change', onMonthSelect, _dbp);
        	p.util.Event.removeListener(_yearDropdown, 'change', onYearSelect, _dbp);
        }  
    };

    this.unbind = function() {
        assertState('bindComplete');
        detachEvents();
        detachListenerForspinner();
        _po = _bindings = _container = _calendarTBody = _dbp = _result = NULL;
        _state = 'init';
    };

    this.getResult = function() {
        assertState('bindComplete');
        return _result;
    };

    this.setResult = function(result) {
        assertState('bindComplete');
        _result = result;
    };

    this.onClose = function(closeReason) {
        var inputsArray = _bindings.associatedElement.getElementsByTagName("input");
        var firstInput = inputsArray[0];
        var imgArray = _bindings.associatedElement.getElementsByTagName("img");
        var imgInput = imgArray.length>0 ? imgArray[0] : false;
      	if (closeReason === 'OK') {
            var args = getSelectedValues();
          	if (_calendarConfig.d[0] === 0) {
                populateInputBox(args);
                if (firstInput.type.toLowerCase() !== "text" && imgInput) {
                    pega.util.Dom.getPreviousSibling(imgInput).focus(); /*Focussing the pxDateTime field after selecting date*/
                    if (p && p.cl && p.cl.isTouchAble()) {
                        pega.util.Dom.getPreviousSibling(imgInput).blur()
                    }
                } else {
                  firstInput.focus(); /*Focussing the pxDateTime field after selecting date for text entry allowed mode*/
                  if(imgInput){
                    imgInput.focus();
                  } else {
                    firstInput.blur();
                  }
                }

            } else {
                populateDropDowns(args);
                if (!p.cl.isTouchAble()) {
                    var selects = _bindings.associatedElement.getElementsByTagName("select");
                    selects[selects.length - 1].focus(); /*For Dropdowns with Calendar, given focus to the right-most dropdown when dismissing the Calendar.*/
                }
            }
            pega.u.d.CalendarUtil.fireClientEvents(_bindings.associatedElement.getElementsByTagName("input")[0]);
        }
        if(closeReason === 'clickaway' || closeReason === 'cancel'){
          if (firstInput.type.toLowerCase() === "text" && imgInput) {
              imgInput.focus();         
          } else{
              firstInput.focus(); /*Focussing the pxDateTime field after selecting date for text entry allowed mode*/
           }
        }
        if (closeReason == 'cancelfireevents') {
            pega.u.d.CalendarUtil.fireClientEvents(_bindings.associatedElement.getElementsByTagName("input")[0]);
        }
        if (pega.env.ua.webkit && pega.cl && pega.cl.isTouchAble()) {
            var tempDisplay = "visible";
            tempDisplay = window.getComputedStyle ? window.getComputedStyle(document.body, "").visibility : document.body.style.visibility;
            document.body.style.visibility = "hidden";
            document.body.offsetHeight;
            document.body.style.visibility = tempDisplay;
            if (this.po) {
                var poContentWrapper = this.po.getContentContainerElement();
                if (poContentWrapper)
                    poContentWrapper.style.padding = '0px';
            }
        }
        /* BUG-813973: START - Clean-up date picker popover markup on close */
        if (_bindings.associatedElement) {
          var inputElement = _bindings.associatedElement;
          var popoOverElement = null;
          var calenderPopupElem = null;
          var calenderPopup = null;
          try {
            if(!pega.util.Dom.inDocument(inputElement)) {
              inputElement = pega.ctx.dom.getElementsByName(inputElement.name)[0];
            }
            var _popOver = p.u.d.getPopOver(inputElement);
            if(_popOver) { popoOverElement = _popOver.getContentContainerElement(); }
            if(popoOverElement) { calenderPopupElem = pega.util.Dom.getElementsById('Pega_Cal_Cont', popoOverElement); }
            if(calenderPopupElem && calenderPopupElem.length == 1) { calenderPopup = calenderPopupElem[0]; }
            if(calenderPopup) { calenderPopup.parentNode.removeChild(calenderPopup); }
          } catch(e) { }
        }
        /* BUG-813973: END */
    };
}
